sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({ api, helpers }) {
  // Fetch the stages from the API response
  const stages = api.data.sam_imp_home_1.output || [];
  console.log(stages);

  // Make sure stages data is available and not empty
  if (stages.length === 0) {
    return `<div>No stages data available.</div>`;
  }

  // Function to dynamically assign classes
  const getStepClass = (index, total) => {
    if (index === 0) return 'start'; // First step is "start"
    if (index === total - 1) return 'current'; // Last step is "current"
    return 'mid'; // Other steps are "mid"
  };

  // Function to generate the step content dynamically
  const generateStep = (stage, index, total) => {
    const stepClass = getStepClass(index, total);
    return `
      <li class="${stepClass}">
        <a style="font-weight: bold;" href="/now/sam-Implementation/${stage.url || '#'}">${stage.stage}</a>
      </li>
    `;
  };

  return `
    <style>
      .stepcontainer {
        display: flex;
        justify-content: center;
        width: 100%;
        margin: 0 auto;
        padding: 0;
        box-sizing: border-box;
      }

      .steps {
        display: flex;
        padding: 0;
        width: 100%;
        overflow: hidden;
        color: white !important;
      }

      .steps li {
        flex: 1;
        height: 70px;
        list-style-type: none;
        padding: 5px 0;
        position: relative;
        box-sizing: border-box;
        text-align: center;
        display: flex;
        justify-content: center;
        align-items: center;
      }

      .steps li:first-child {
        padding-left: 5px;
      }

      .steps li:nth-child(n + 2)::before {
        position: absolute;
        top: 0;
        left: 0;
        display: block;
        border-left: 24px solid white;
        border-top: 40px solid transparent;
        border-bottom: 40px solid transparent;
        width: 0;
        height: 0;
        content: " ";
      }

      .steps li::after {
        z-index: 1;
        position: absolute;
        top: 0;
        right: -24px;
        display: block;
        border-left: 25px solid #84e78c;
        border-top: 40px solid transparent;
        border-bottom: 40px solid transparent;
        width: 0;
        height: 0;
        content: " ";
      }

      .steps li.start {
        background-color: #4F52BD;
      }

      .steps li.start::after {
        border-left-color: #4F52BD;
      }

      .steps li.mid {
        background-color: #3A3D88;
        border-left: 3px solid white;
      }

      .steps li.mid::after {
        border-left-color: #3A3D88;
      }

      .steps li.current {
        background-color: #0F121B;
        border-left: 3px solid white;
      }

      .steps li.current::after {
        border-left-color: #0F121B;
      }

      .steps li a {
        color: inherit;
        text-decoration: none;
        display: block;
        width: 100%;
        height: 100%;
        text-align: center;
        line-height: 70px;
        display: flex;
        justify-content: center;
        align-items: center;
      }
    </style>

    <div class="stepcontainer">
      <ul class="steps">
        ${stages.map((stage, index) => generateStep(stage, index, stages.length)).join('')}
      </ul>
    </div>
  `;
}
